import java.util.*;

class GenericList<E> {
    private E[] con;
    private int size;

    public GenericList() { }

public GenericList<E> copyWithoutTarget(E target) {
    GenericList<E> result = new GenericList<>();
    result.con = (E[]) new Object[size + 10];
    for (int i = 0; i < size; i++) {
        if (!con[i].equals(target)) {
            result.con[result.size] = con[i];
            result.size++;
        }
    }
    return result;
}

    @SafeVarargs
    static <T> GenericList<T> of(T... vals) {
        GenericList<T> list = new GenericList<>();
        list.con = (T[]) new Object[vals.length + 5];
        for (T val : vals) {
            list.con[list.size++] = val;
        }
        return list;
    }

    int sizeForTest() { return size; }
    int capacityForTest() { return con == null ? 0 : con.length; }
    public String toString() {
        return Arrays.toString(Arrays.copyOf(con, size));
    }
}

