import java.util.*;

class IntBST {
    private IntNode root;

    private static class IntNode {
        private int val;
        private IntNode left;
        private IntNode right;
        private IntNode(int val) { this.val = val; }
    }

public int numInRange(int low, int high) {
    return help(root, low, high);
}

private int help(IntNode n, int low, int high) {
    if (n == null) {
        return 0;
    } else if (n.val < low) {
        return help(n.right, low, high);
    } else if (n.val > high) {
        return help(n.left, low, high);
    } else {
        return 1 + help(n.left, low, high) + help(n.right, low, high);
    }
}

    void add(int val) {
        root = add(root, val);
    }

    private IntNode add(IntNode node, int val) {
        if (node == null) return new IntNode(val);
        if (val <= node.val) node.left = add(node.left, val);
        else node.right = add(node.right, val);
        return node;
    }

