import java.util.*;

class HashTable314<E> implements Iterable<E> {
    private List<E>[] con;
    private int size;

    public HashTable314(int cap) {
        con = new List[cap];
    }

    public Iterator<E> iterator() { return new HIterator(); }

private class HIterator implements Iterator<E> {
    private int numToReturn;
    private int bucketIndex;
    private Iterator<E> currentIterator;

    private HIterator() {
        numToReturn = size;
        if (numToReturn > 0) {
            findNextBucket();
        }
    }

    private void findNextBucket() {
        while (con[bucketIndex] == null) {
            bucketIndex++;
        }
        currentIterator = con[bucketIndex].iterator();
    }

    public boolean hasNext() {
        return numToReturn > 0;
    }

    public E next() {
        numToReturn--;
        if (!currentIterator.hasNext()) {
            bucketIndex++;
            findNextBucket();
        }
        return currentIterator.next();
    }

    public void remove() {
        currentIterator.remove();
        size--;
        if (con[bucketIndex].size() == 0) {
            con[bucketIndex] = null;
        }
    }
}

    void addToBucket(int bucket, E val) {
        if (con[bucket] == null) {
            con[bucket] = new LinkedList<>();
        }
        con[bucket].add(val);
        size++;
    }

    int sizeForTest() { return size; }
    boolean bucketIsNullForTest(int bucket) { return con[bucket] == null; }
}

