import java.util.*;
import java.io.*;

public class StudentSolution {
public static int coinsCollected(int[][] mat, int initialRow) {
    int col = 0;
    int row = initialRow;
    int total = 0;
    while (col < mat[0].length - 1) {
        total += mat[row][col];
        mat[row][col] = -1;
        int up = -1;
        if (row > 0) {
            up = mat[row - 1][col];
        }
        int down = -1;
        if (row + 1 < mat.length) {
            down = mat[row + 1][col];
        }
        int right = mat[row][col + 1];
        if (up >= down && up >= right) {
            row--;
        } else if (down >= up && down >= right) {
            row++;
        } else {
            col++;
        }
    }
    total += mat[row][col];
    return total;
}
}

